END=85.57;cues=[];words=[]
for i,(t0,txt) in enumerate(C):
    t1=C[i+1][0] if i+1<len(C) else END
    cues.append(dict(s=t0,e=round(t1,3),t=txt))
    ws=txt.split();wt=[len(w)+1.5 for w in ws];tot=sum(wt);span=(t1-t0)*0.92;t=t0
    for w,x in zip(ws,wt):
        d=span*x/tot;words.append(dict(w=w,s=round(t,3),e=round(t+d,3),c=i));t+=d
F=json.load(open('web/faces.json'))
